INSERT INTO dump_descriptions (base_key, description) VALUES ('arcammunition_english', 'English text add-on for Flying_Dickcat’s Minigun Arc Ammunition overclock; the author used Google Translate and guesswork, so wording may be off.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('time4tests', 'Sandbox test mod with hotkeys for global time dilation: 0 toggles pause, - cycles 1/0.1/0.05, and = cycles 1/2/8. Zero dilation can leave the cursor stuck; client effects may differ.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('checkresup', 'Server-side chat messages announce when a resupply is available at the configured nitra cost, report a modified cost, and say when no more resupplies are possible.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('noplantcarve', 'Host-side mod that removes terrain carving from exploding puffballs (exploding plants), including in Fungus Bogs and Magma Core.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
